*{box-sizing:border-box}body{margin:0;font-family:Inter,Arial,sans-serif;color:#17202a;background:#eef2f5}.app{display:grid;grid-template-columns:430px 1fr;height:100vh}.side{background:#fff;padding:18px;overflow:auto;box-shadow:2px 0 12px #0001;z-index:2}.tabs{display:grid;grid-template-columns:repeat(3,1fr);gap:5px;margin:16px 0}.tabs button{border:0;background:#e9edf1;padding:11px 5px;border-radius:8px;cursor:pointer}.tabs button.active{background:#17202a;color:#fff}.panel{display:none}.panel.active{display:block}.row{display:grid;grid-template-columns:1fr 1fr;gap:8px}.step{margin:15px 0 8px;font-weight:700}label{display:block;font-size:12px;margin:8px 0}input,select,button{font:inherit}input,select{width:100%;padding:9px;border:1px solid #ccd3d9;border-radius:7px;margin-top:4px}button.action{width:100%;padding:12px;border:0;border-radius:8px;background:#1f6feb;color:#fff;cursor:pointer;margin-top:12px}.secondary{width:100%;padding:9px;border:1px solid #ccd3d9;background:#f6f8fa;border-radius:7px;cursor:pointer;margin-top:5px}.status{margin-top:12px;font-size:13px;min-height:22px}.progress{height:7px;background:#e7ebef;border-radius:9px;overflow:hidden;margin-top:7px;display:none}.progress i{display:block;height:100%;width:0;background:#1f6feb;transition:width .25s}.result{margin-top:12px;font-size:13px}.window{border-top:1px solid #ddd;padding:9px 0}.map{height:100%;width:100%}.hint{position:absolute;top:12px;right:12px;background:#fff;padding:8px 12px;border-radius:7px;z-index:1000;box-shadow:0 2px 8px #0002}.note{font-size:11px;color:#667;margin-top:6px}.advanced{border:1px solid #d8dde2;border-radius:9px;padding:10px;margin-top:12px}.advanced summary{cursor:pointer;font-weight:700}.opt{display:grid;grid-template-columns:20px 1fr;gap:7px;align-items:start;margin:10px 0}.opt input[type=checkbox]{width:auto;margin:3px 0}.opt .field{display:grid;grid-template-columns:1fr 90px;gap:7px;align-items:center}.opt .field input{margin:0}.levels{font-size:11px;color:#667;background:#f5f7f9;border-radius:7px;padding:8px;margin-top:8px;line-height:1.5}
