<script src="https://unpkg.com/leaflet@1.9.4/dist/leaflet.js"></script><script>
const map=L.map('map').setView([44.67,34.41],7);L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'© OpenStreetMap'}).addTo(map);let mode='direct',lines=[],targetMarker=null,launchMarker=null;const now=new Date();const local=d=>new Date(d-d.getTimezoneOffset()*60000).toISOString().slice(0,16);dtime.value=local(now);btime.value=local(now);fs.value=local(now);fe.value=local(new Date(now.getTime()+6*3600000));
document.querySelectorAll('.tab').forEach(b=>b.onclick=()=>{document.querySelectorAll('.tab').forEach(x=>x.classList.remove('active'));b.classList.add('active');document.querySelectorAll('.panel').forEach(x=>x.classList.remove('active'));document.getElementById(b.dataset.panel).classList.add('active');mode=b.dataset.panel});
function status(s,err=false){document.getElementById('status').textContent=s;document.getElementById('status').style.color=err?'#c00':''}function progress(v,show=true){const p=document.getElementById('progress');p.style.display=show?'block':'none';p.firstElementChild.style.width=Math.max(0,Math.min(100,v))+'%'}function clearLines(){lines.forEach(x=>map.removeLayer(x));lines=[];hideTrajectoryInfo()}function esc(v){return String(v??'').replace(/[&<>\"]/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;'}[m]))}
const trajectoryInfo=document.getElementById('trajectoryInfo');let trajectoryInfoTimer=null;
function num(v,d=0){const n=Number(v);return Number.isFinite(n)?n:d}
function trajectoryValue(p,keys,d=0){for(const k of keys){if(p&&p[k]!=null&&Number.isFinite(Number(p[k])))return Number(p[k]);}return d}
function chartSvg(points,keyKeys,label,unit){const vals=points.map(p=>trajectoryValue(p,keyKeys)).filter(Number.isFinite);if(vals.length<2)return '<div class="note">Недостаточно точек для графика.</div>';const w=400,h=120,pad=24,min=Math.min(...vals),max=Math.max(...vals),range=Math.max(1e-9,max-min);const path=points.map((p,i)=>{const v=trajectoryValue(p,keyKeys);const x=pad+(w-2*pad)*i/Math.max(1,points.length-1);const y=h-pad-(h-2*pad)*(v-min)/range;return (i?'L':'M')+x.toFixed(1)+' '+y.toFixed(1)}).join(' ');const mid=(min+max)/2;return '<div class="trajectory-chart-title">'+esc(label)+' ('+esc(unit)+')</div><svg class="trajectory-chart" viewBox="0 0 '+w+' '+h+'" preserveAspectRatio="none"><line x1="'+pad+'" y1="'+pad+'" x2="'+pad+'" y2="'+(h-pad)+'" stroke="#cfd6dc"/><line x1="'+pad+'" y1="'+(h-pad)+'" x2="'+(w-pad)+'" y2="'+(h-pad)+'" stroke="#cfd6dc"/><path d="'+path+'" fill="none" stroke="#1f6feb" stroke-width="2"/><text x="3" y="'+(pad+4)+'" font-size="9" fill="#667">'+max.toFixed(0)+'</text><text x="3" y="'+(h-pad)+'" font-size="9" fill="#667">'+min.toFixed(0)+'</text><text x="'+(w-45)+'" y="'+(h-4)+'" font-size="9" fill="#667">'+esc(points[points.length-1].time?new Date(points[points.length-1].time).toLocaleTimeString():'')+'</text><text x="'+(w/2-18)+'" y="'+(h-4)+'" font-size="9" fill="#667">'+esc(points[0].time?new Date(points[0].time).toLocaleTimeString():'')+'</text></svg>'}
function showTrajectoryInfo(points,title,ev){if(!points||points.length<2)return;const alts=points.map(p=>trajectoryValue(p,['altitude_m','altitude'])),speeds=points.map(p=>trajectoryValue(p,['speed_mps','wind_speed_mps','ground_speed_mps']));const first=points[0],last=points[points.length-1],maxAlt=Math.max(...alts),maxSpeed=Math.max(...speeds);trajectoryInfo.innerHTML='<button class="trajectory-close" onclick="hideTrajectoryInfo()">×</button><h4>'+esc(title||'Траектория')+'</h4><div class="trajectory-stats"><div><b>Начало:</b> '+esc(first.time?new Date(first.time).toLocaleString():'—')+'</div><div><b>Конец:</b> '+esc(last.time?new Date(last.time).toLocaleString():'—')+'</div><div><b>Высота в конце:</b> '+Math.round(alts[alts.length-1])+' м</div><div><b>Макс. высота:</b> '+Math.round(maxAlt)+' м</div><div><b>Скорость в конце:</b> '+speeds[speeds.length-1].toFixed(2)+' м/с</div><div><b>Макс. скорость:</b> '+maxSpeed.toFixed(2)+' м/с</div><div><b>Точек:</b> '+points.length+'</div><div><b>Шаг:</b> '+(points.length>1&&first.time&&last.time?((new Date(last.time)-new Date(first.time))/1000/(points.length-1)/60).toFixed(1)+' мин':'—')+'</div></div>'+chartSvg(points,['altitude_m','altitude'],'Высота','м')+chartSvg(points,['speed_mps','wind_speed_mps','ground_speed_mps'],'Скорость','м/с');trajectoryInfo.style.display='block';positionTrajectoryInfo(ev)}
function positionTrajectoryInfo(ev){if(!ev)return;const margin=12,w=trajectoryInfo.offsetWidth,h=trajectoryInfo.offsetHeight;let x=ev.clientX+16,y=ev.clientY+16;if(x+w>window.innerWidth-margin)x=ev.clientX-w-16;if(y+h>window.innerHeight-margin)y=window.innerHeight-h-margin;trajectoryInfo.style.left=Math.max(margin,x)+'px';trajectoryInfo.style.top=Math.max(margin,y)+'px'}
function hideTrajectoryInfo(){clearTimeout(trajectoryInfoTimer);trajectoryInfo.style.display='none'}
trajectoryInfo.addEventListener('mouseenter',()=>clearTimeout(trajectoryInfoTimer));trajectoryInfo.addEventListener('mouseleave',()=>{trajectoryInfoTimer=setTimeout(hideTrajectoryInfo,180)});
function line(points,color='#1f6feb',weight=3,title='Траектория'){if(!points||points.length<2)return null;const l=L.polyline(points.map(p=>[p.lat,p.lon]),{color,weight}).addTo(map);l._trajectoryPoints=points;l._trajectoryTitle=title;lines.push(l);l.on('mouseover',e=>{l.setStyle({weight:Math.max(weight+2,5)});clearTimeout(trajectoryInfoTimer);showTrajectoryInfo(points,title,e.originalEvent)});l.on('mousemove',e=>{if(trajectoryInfo.style.display==='block')positionTrajectoryInfo(e.originalEvent)});l.on('mouseout',()=>{l.setStyle({weight});trajectoryInfoTimer=setTimeout(hideTrajectoryInfo,220)});return l}function fitAll(){if(lines.length){const g=L.featureGroup(lines);map.fitBounds(g.getBounds().pad(.15))}}
function markPoint(kind,la,lo){const m=L.marker([la,lo]).addTo(map);if(kind==='targetMarker'){if(targetMarker)map.removeLayer(targetMarker);targetMarker=m}else{if(launchMarker)map.removeLayer(launchMarker);launchMarker=m}}
function pick(m){mode=m;status('Кликните по карте');map.once('click',e=>{const la=e.latlng.lat.toFixed(6),lo=e.latlng.lng.toFixed(6);if(m==='direct'){dlat.value=la;dlon.value=lo}else if(m==='back'){blat.value=la;blon.value=lo}else if(m==='target'){tlat.value=la;tlon.value=lo;markPoint('targetMarker',+la,+lo)}else{clat.value=la;clon.value=lo;markPoint('launchMarker',+la,+lo)}status('Точка установлена')})}
</script></body></html>
